import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

# Build lookup: project_basename -> framework -> package_id -> resolved_version
def build_map(data):
    m = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw.get('topLevelPackages', []):
                key = (name, fw['framework'], pkg['id'])
                m[key] = pkg['resolvedVersion']
    return m

b = build_map(baseline)
a = build_map(after)

all_keys = sorted(set(b.keys()) | set(a.keys()))
changes = []
unchanged = []
for k in all_keys:
    bv = b.get(k, '—')
    av = a.get(k, '—')
    if bv != av:
        changes.append((*k, bv, av))
    else:
        unchanged.append((*k, av))

print('=== CHANGES ===')
if changes:
    for proj, fw, pkg, bv, av in changes:
        print(f'  {proj} ({fw}) | {pkg} | {bv} -> {av}')
else:
    print('  None')

print()
print(f'=== UNCHANGED ({len(unchanged)} entries) ===')
for proj, fw, pkg, v in unchanged:
    print(f'  {proj} ({fw}) | {pkg} | {v}')
"

